-- Restore Blackwing Lair caches 1278066, 1278068 and 1278069.
-- One per guaranteed family; 10% independent optional families.
-- Mythic BWL: 50% second Heroic item; 11-20 Dungeon ranks intentionally advertised.
-- AtlasLootAscension Classic BWL catalogue and captured item export identities.
-- Source: docs/BLACKWING_LAIR_CACHE_CANDIDATES.csv and mapping report.
-- Heroic Shadow Flame Legguards is missing; no cross-tier substitution.
-- Self-contained seven pools; no dependency on SQL 26/53/54/55.
-- Keeps scriptless HAS_LOOT opening, existing progression and stat preference.
-- Grouped roots plus scoped C++ guard stabilize odds and per-family counts.
-- Rebuild the module, apply to acore_world and restart worldserver.

DROP TEMPORARY TABLE IF EXISTS `tmp_ms_bwl_candidate`;
CREATE TEMPORARY TABLE `tmp_ms_bwl_candidate` (
    `Pool` INT UNSIGNED NOT NULL,
    `Item` INT UNSIGNED NOT NULL,
    `Name` VARCHAR(255) NOT NULL,
    `Class` TINYINT UNSIGNED NOT NULL,
    `Subclass` TINYINT UNSIGNED NOT NULL,
    `InventoryType` TINYINT UNSIGNED NOT NULL,
    `Quality` TINYINT UNSIGNED NOT NULL,
    `RequiredLevel` INT UNSIGNED NOT NULL,
    `DisplayId` INT UNSIGNED NOT NULL,
    `ItemLevel` INT UNSIGNED NOT NULL,
    `Description` TEXT NOT NULL,
    PRIMARY KEY (`Pool`, `Item`)
) ENGINE=InnoDB;

DELETE FROM `tmp_ms_bwl_candidate`;
