DROP PROCEDURE IF EXISTS `ms_bwl_cache_restore_20261007`;
DELIMITER $$
CREATE PROCEDURE `ms_bwl_cache_restore_20261007`()
BEGIN
    DECLARE `normal_bwl` INT UNSIGNED DEFAULT 0;
    DECLARE `heroic_bwl` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_bwl` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_mc` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_onyxia` INT UNSIGNED DEFAULT 0;
    DECLARE `ascended_onyxia` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_11_20` INT UNSIGNED DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    IF (SELECT COUNT(*) FROM `information_schema`.`TABLES`
        WHERE `TABLE_SCHEMA` = DATABASE() AND `TABLE_NAME` IN ('item_loot_template', 'reference_loot_template')
            AND `ENGINE` = 'InnoDB') <> 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: InnoDB loot tables required';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM `tmp_ms_bwl_candidate`) <> 6489 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: expected 6489 candidate assignments';
    END IF;
    -- One scan: MySQL cannot reopen a temporary table twice in one statement.
    SELECT COUNT(CASE WHEN `Pool` = 9003401 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003402 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003403 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003404 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003405 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003406 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003407 THEN 1 END)
    INTO `normal_bwl`, `heroic_bwl`, `mythic_bwl`, `mythic_mc`,
        `mythic_onyxia`, `ascended_onyxia`, `dungeon_11_20`
    FROM `tmp_ms_bwl_candidate`;
    IF `normal_bwl` <> 82 OR `heroic_bwl` <> 81 OR `mythic_bwl` <> 82
        OR `mythic_mc` <> 106 OR `mythic_onyxia` <> 14
        OR `ascended_onyxia` <> 14 OR `dungeon_11_20` <> 6110 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: candidate family count mismatch';
    END IF;
    IF (SELECT COUNT(*) FROM `item_template`
        WHERE `entry` IN (1278066, 1278068, 1278069) AND (`Flags` & 4) <> 0 AND `ScriptName` = '') <> 3 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: missing scriptless HAS_LOOT containers';
    END IF;
    IF EXISTS (
        SELECT 1 FROM `tmp_ms_bwl_candidate` AS `c`
        LEFT JOIN `item_template` AS `i` ON `i`.`entry` = `c`.`Item`
        WHERE `i`.`entry` IS NULL
            OR `i`.`class` <> `c`.`Class` OR `i`.`subclass` <> `c`.`Subclass`
            OR `i`.`InventoryType` <> `c`.`InventoryType` OR `i`.`Quality` <> `c`.`Quality`
            OR `i`.`RequiredLevel` <> `c`.`RequiredLevel` OR `i`.`displayid` <> `c`.`DisplayId`
            OR `i`.`ItemLevel` <> `c`.`ItemLevel`
            OR (`c`.`Description` LIKE '@%' AND BINARY `i`.`description` <> BINARY `c`.`Description`)
            OR `i`.`RequiredLevel` > 60 OR `i`.`class` NOT IN (2, 4) OR `i`.`InventoryType` = 0
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: candidate metadata mismatch';
    END IF;
    IF EXISTS (SELECT 1 FROM `reference_loot_template`
        WHERE `Entry` IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407)
            AND `Comment` <> 'MS Classic BWL cache family pool')
        OR EXISTS (SELECT 1 FROM `reference_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `item_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407)
                AND `Entry` NOT IN (1278066, 1278068, 1278069)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: reserved reference namespace collision';
    END IF;
    IF EXISTS (SELECT 1 FROM `creature_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `disenchant_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `fishing_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `gameobject_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `mail_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `milling_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `pickpocketing_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `prospecting_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `skinning_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `spell_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407))
        OR EXISTS (SELECT 1 FROM `player_loot_template`
            WHERE ABS(`Reference`) IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: references used by another loot store';
    END IF;
    IF EXISTS (SELECT 1 FROM `conditions`
        WHERE (`SourceTypeOrReferenceId` = 10
            AND `SourceGroup` IN (9003401,9003402,9003403,9003404,9003405,9003406,9003407))
            OR (`SourceTypeOrReferenceId` = 5 AND `SourceGroup` IN (1278066,1278068,1278069))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: existing loot conditions require review';
    END IF;
    DELETE FROM `reference_loot_template`
    WHERE `Entry` IN (9003401, 9003402, 9003403, 9003404, 9003405, 9003406, 9003407);
    INSERT INTO `reference_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    SELECT `Pool`, `Item`, 0, 0, 0, 1, 1, 1, 1, 'MS Classic BWL cache family pool'
    FROM `tmp_ms_bwl_candidate`;
    DELETE FROM `item_loot_template` WHERE `Entry` IN (1278066, 1278068, 1278069);
    INSERT INTO `item_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    VALUES
    (1278066, 1, 9003404, 100, 0, 1, 1, 1, 1, 'MS BWL: guaranteed Mythic MC'),
    (1278066, 2, 9003401, 100, 0, 1, 2, 1, 1, 'MS BWL: guaranteed Normal BWL'),
    (1278066, 3, 9003405, 10, 0, 1, 3, 1, 1, 'MS BWL: optional Mythic Onyxia'),
    (1278066, 4, 9003407, 10, 0, 1, 4, 1, 1, 'MS BWL: optional Mythic 11-20 Dungeon'),
    (1278068, 1, 9003401, 100, 0, 1, 1, 1, 1, 'MS BWL: guaranteed Normal BWL'),
    (1278068, 2, 9003406, 10, 0, 1, 2, 1, 1, 'MS BWL: optional Ascended Onyxia'),
    (1278068, 3, 9003402, 10, 0, 1, 3, 1, 1, 'MS BWL: optional Heroic BWL'),
    (1278068, 4, 9003407, 10, 0, 1, 4, 1, 1, 'MS BWL: optional Mythic 11-20 Dungeon'),
    (1278069, 1, 9003402, 100, 0, 1, 1, 1, 1, 'MS BWL: guaranteed Heroic BWL'),
    (1278069, 2, 9003402, 50, 0, 1, 2, 1, 1, 'MS BWL: optional second Heroic BWL'),
    (1278069, 3, 9003403, 10, 0, 1, 3, 1, 1, 'MS BWL: optional Mythic BWL'),
    (1278069, 4, 9003406, 10, 0, 1, 4, 1, 1, 'MS BWL: optional Ascended Onyxia'),
    (1278069, 5, 9003407, 10, 0, 1, 5, 1, 1, 'MS BWL: optional Mythic 11-20 Dungeon');
    IF (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278066) <> 4
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278068) <> 4
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278069) <> 5
        OR (SELECT COUNT(*) FROM `reference_loot_template`
            WHERE `Entry` IN (9003401,9003402,9003403,9003404,9003405,9003406,9003407)) <> 6489 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BWL caches: post-write row count mismatch';
    END IF;
    COMMIT;
END$$
DELIMITER ;
CALL `ms_bwl_cache_restore_20261007`();
DROP PROCEDURE `ms_bwl_cache_restore_20261007`;

SELECT `Entry`, `Reference`, `Chance`, `GroupId`, `MinCount`, `MaxCount`
FROM `item_loot_template` WHERE `Entry` IN (1278066,1278068,1278069) ORDER BY `Entry`, `Item`;
SELECT `Entry`, COUNT(*) AS `Candidates`
FROM `reference_loot_template`
    WHERE `Entry` IN (9003401,9003402,9003403,9003404,9003405,9003406,9003407)
GROUP BY `Entry`;
DROP TEMPORARY TABLE `tmp_ms_bwl_candidate`;
